-- Errata reading for M17: Same-day contact included (0-7 days after the ED date).
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream='encounters'), e AS (SELECT patient, json_extract(payload,'$.encounter_id') eid, json_extract(payload,'$.type') t, min(json_extract(payload,'$.event_date')) d FROM r GROUP BY 1,2,3), ed AS (SELECT * FROM e WHERE t IN ('emergency','ED','ED stroke alert') AND d BETWEEN '2029-01-01' AND '2029-08-15'), fu AS (SELECT DISTINCT ed.eid FROM ed JOIN e f ON f.patient=ed.patient AND f.t IN ('primary_care','office','pediatric_office','wellness','specialist_office','specialty_followup','telephone') AND julianday(f.d)-julianday(ed.d) BETWEEN 0 AND 7) SELECT ROUND(100.0*(SELECT COUNT(*) FROM fu)/(SELECT COUNT(*) FROM ed),1) AS value;
